package org.example;
import javafx.application.Platform;import javafx.scene.Scene;import javafx.scene.control.*;import javafx.stage.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIf;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.example.FxTestSupport.fx;import static org.junit.jupiter.api.Assertions.*;
@EnabledIf("org.example.FxTestSupport#isGuiAvailable")
class AdvancedPlannerInterfaceTest {
 @TempDir Path root;
 @Test void actualHistoryFormSavesGradeAndAlternativesRequireExplicitApplication()throws Exception{
  FxTestSupport.initialize();var model=AdvancedCoursePlannerTest.model();Path file=root.resolve("data/courses/curricula.json");var storage=new CurriculumStorageService(file);storage.load();storage.save(AdvancedCoursePlannerTest.plan(AdvancedCoursePlannerTest.degree("A",model,Map.of())));
  var catalog=AdvancedCoursePlannerTest.catalog(AdvancedCoursePlannerTest.section("a","CS101",1,"09:00","10:00","A"),AdvancedCoursePlannerTest.section("b","CS201",1,"10:00","11:00","B"));AtomicReference<CourseData> applied=new AtomicReference<>();AtomicReference<Throwable> formFailure=new AtomicReference<>();AdvancedCoursePlannerView[] view=new AdvancedCoursePlannerView[1];Stage[] window=new Stage[1];
  fx(()->{view[0]=new AdvancedCoursePlannerView(root,applied::set);view[0].update(catalog);window[0]=new Stage();window[0].setTitle("Academic OS Advanced Planner Verification");window[0].setScene(new Scene(view[0],1200,780));window[0].show();return null;});
  try{
   waitFor(()->text(window[0]).contains("Müfredatlar yüklendi"));
   fx(()->{Platform.runLater(()->{try{var dialog=dialog(window[0]);@SuppressWarnings("unchecked")ListView<Object> list=(ListView<Object>)dialog.getScene().lookup("#curriculum-history-list");list.getSelectionModel().selectFirst();Platform.runLater(()->{try{var nested=Window.getWindows().stream().filter(w->w instanceof Stage&&w.isShowing()&&w.getScene().lookup("#history-grade")!=null).map(Stage.class::cast).findFirst().orElseThrow();@SuppressWarnings("unchecked")ComboBox<String> status=(ComboBox<String>)nested.getScene().lookup("#history-status");status.getSelectionModel().select(2);((TextField)nested.getScene().lookup("#history-grade")).setText("AA");((Button)nested.getScene().lookup("#advanced-form-save")).fire();}catch(Throwable t){formFailure.set(t);}});((Button)dialog.getScene().lookup("#history-edit")).fire();((CheckBox)dialog.getScene().lookup("#history-reviewed")).setSelected(true);((Button)dialog.getScene().lookup("#advanced-form-save")).fire();}catch(Throwable t){formFailure.set(t);}});((Button)window[0].getScene().lookup("#curriculum-history")).fire();return null;});
   if(formFailure.get()!=null)throw new AssertionError(formFailure.get());waitFor(()->text(window[0]).contains("kaydedildi"));assertEquals("AA",storage.load().degrees().getFirst().decisions().get("1:1").grade());
   fx(()->{((DatePicker)window[0].getScene().lookup("#alternative-start")).setValue(AdvancedCoursePlannerTest.START);((DatePicker)window[0].getScene().lookup("#alternative-end")).setValue(AdvancedCoursePlannerTest.END);((Button)window[0].getScene().lookup("#alternative-generate")).fire();return null;});waitFor(()->text(window[0]).contains("alternatif bulundu"));assertNull(applied.get());
   fx(()->{view[0].applyCss();view[0].layout();Path shot=Path.of("build/reports/advanced-planner.png");Files.createDirectories(shot.getParent());var capture=view[0].snapshot(null,null);var pixels=new BufferedImage((int)capture.getWidth(),(int)capture.getHeight(),BufferedImage.TYPE_INT_ARGB);for(int y=0;y<pixels.getHeight();y++)for(int x=0;x<pixels.getWidth();x++)pixels.setRGB(x,y,capture.getPixelReader().getArgb(x,y));ImageIO.write(pixels,"png",shot.toFile());Platform.runLater(()->{try{var alert=dialog(window[0]);alert.getScene().getRoot().lookupAll(".button").stream().filter(Button.class::isInstance).map(Button.class::cast).filter(b->b.getText().equals("OK")||b.getText().equals("Tamam")).findFirst().orElseThrow().fire();}catch(Throwable t){formFailure.set(t);}});((Button)window[0].getScene().lookup("#alternative-apply-1")).fire();return null;});if(formFailure.get()!=null)throw new AssertionError(formFailure.get());assertNotNull(applied.get());assertEquals("CS201",applied.get().courses().getFirst().code());
  }finally{fx(()->{view[0].dispose();window[0].close();return null;});}
 }
 private static Stage dialog(Window owner){return Window.getWindows().stream().filter(w->w instanceof Stage s&&s.getOwner()==owner&&w.isShowing()).map(Stage.class::cast).findFirst().orElseThrow();}
 private static String text(Stage window){try{return fx(()->((Label)window.getScene().lookup("#advanced-planner-status")).getText());}catch(Exception e){throw new RuntimeException(e);}}
 private static void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);while(!condition.getAsBoolean()&&System.nanoTime()<until)Thread.sleep(20);assertTrue(condition.getAsBoolean());}
}
